(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sl"] = {"ui":{"skip":"Preskoči na vsebino","back":"← Nazaj na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Izberi jezik","lang.search":"Išči jezike","lang.none":"Noben jezik se ne ujema","lang.notYet":"{name} še ni preveden","theme.aria":"Preklopi med svetlo in temno temo","theme.toLight":"Preklopi na svetlo temo","theme.toDark":"Preklopi na temno temo","index.title":"AI-gile: tvoja AI razvojna ekipa na eni tabli","index.description":"AI-gile je kanban tabla za ekipe AI programerjev. Delajo, medtem ko spiš; ti dobiš eno kratko skupino reči, o katerih odločiš, jih preizkusiš in sprejmeš.","hero.logoAlt":"Ikona table AI-gile","hero.h1.html":"Tvoja AI razvojna ekipa na eni&nbsp;tabli.","hero.alpha":"🐣 Zaprta pred-alfa","hero.alphaTitle":"Zgodnja in nedokončana različica: hvala, da jo preizkušaš!","hero.lede":"Gradijo, medtem ko spiš. Zjutraj te čaka ena kratka skupina: nekaj vprašanj, nekaj reči za preizkus, kak vijoličen diamant. Klik, sprejem in nazaj h kavi.","dl.windows":"Aplikacija za Windows","dl.browser":"Zaženi v brskalniku","dl.soon":"Kmalu","dl.notify":"🔔 Sporoči mi, ko se odpre","dl.notifySmall":"Alfa ali beta","hero.secondary":"Agilno, le da ekipa nikoli ne potrebuje jutranje kave na stand-upu. (Stand-upe imajo vseeno.)","pitch.h2":"AI-gile v toliko besedah, kolikor jih želiš","pitch.lede":"Izberi dolžino, od ene besede do 144. Vsaka dolžina je svoj opis, napisan prav zanjo. Povleci drsnik ali uporabi puščice.","pitch.rangeLabel":"Dolžina v besedah","pitch.dice":"🎲 druga različica","pitch.words.one":"{n} beseda","pitch.words.two":"{n} besedi","pitch.words.few":"{n} besede","pitch.words.other":"{n} besed","pitch.letters.one":"{n} črka","pitch.letters.two":"{n} črki","pitch.letters.few":"{n} črke","pitch.letters.other":"{n} črk","pitch.chars.one":"{n} znak","pitch.chars.two":"{n} znaka","pitch.chars.few":"{n} znaki","pitch.chars.other":"{n} znakov","count.line.html.one":"{n} kartica je zdaj na tabli","count.line.html.two":"{n} kartici sta zdaj na tabli","count.line.html.few":"{n} kartice so zdaj na tabli","count.line.html.other":"{n} kartic je zdaj na tabli","features.aria":"Kaj počne","f.pile.h":"Ena skupina zate","f.pile.html":"<b>Zate</b> zbere vse, kar čaka nate, čez vse projekte: vprašanja, reči za preizkus, naloge, ki jih zmore le človek. Tvoja vrsta pove, kaj je na vrsti in koliko časa bo trajalo.","f.sleep.h":"Ekipe, ki delajo, medtem ko spiš","f.sleep.p":"Vsak projekt ima vodjo in ekipo AI agentov. Napiši komentar h kartici in ekipa se zbudi, opravi delo in ti ga vrne s koraki, ki jih zmore tudi utrujen človek.","f.tester.h":"Najprej preveri AI testnik","f.tester.p":"Preden karkoli pride do tebe, testnik v kopiji aplikacije sledi korakom in pokaže, kaj je videl, s posnetkom zaslona. Preleti uspešne in sprejmi z enim klikom.","f.proof.h":"Dokazi, ne obljube","f.proof.p":"Vsaka predaja pokaže, kaj se je spremenilo: datoteke, razlike, posnetke zaslona. Ni treba odpirati vsake aplikacije, da vidiš, ali je končano.","f.chat.h":"Klepet z vodji","f.chat.p":"Stranska vrstica kot na Discordu: ena ikona na projekt, vijolični diamanti za to, kar potrebuje tebe. Vodji pošlji idejo; ta jo spremeni v kartice in načrt z gumbom ✅ Daj.","f.tidy.h":"Sam skrbi za red","f.tidy.p":"Sorodne kartice se združijo, zmedeni naslovi se popravijo, preverjanje žetonov pa drži kodo vitko. Manj stvari za preklapljanje, manj za razmišljanje.","f.private.h":"Tvoje, na tvojem računalniku","f.private.li1":"Tabla teče na tvojem računalniku in odgovarja samo tebi.","f.private.li2":"Zasebna sporočila med ljudmi so šifrirana od konca do konca.","f.private.li3":"Brez računov, brez sledilnikov, brez piškotkov.","f.lang.h":"V tvojem jeziku","f.lang.p":"Več kot 120 jezikov, od nizozemščine, valižanščine in japonščine do piratščine, Yodove govorice in klingonščine, s hitrim preklopom nazaj v angleščino za razvijalske besede.","tl.aria":"Časovnica od prvega pogovora do načrta","tl.h2":"Od prvega klepeta do tega, kar sledi","tl.lede":"Pravi datumi in ure v tvojem časovnem pasu. Po današnjem dnevu je to načrt, brez obljubljenih datumov.","tl.today":"Danes","tl.planned":"načrtovano","tl.cards.one":"{n} kartica","tl.cards.two":"{n} kartici","tl.cards.few":"{n} kartice","tl.cards.other":"{n} kartic","join.h2":"Pridruži se","join.lede":"AI-gile gradi en majhen človek in veliko potrpežljivih agentov. Zaenkrat je zasebna, v zaprti alfi s prijatelji. Bi ga rad preizkusil, ko se odpre?","join.btn":"Sporoči zanimanje","join.small":"Pisali ti bomo po e-pošti, nič drugega","footer.tag":"AI-gile. Brez sledilnikov, brez piškotkov, brez kave na stand-upu.","footer.licence":"Poslovna licenca","footer.status":"Stanje","form.sending":"Pošiljanje …","form.failed":"Ni uspelo: poskusi znova pozneje.","form.offline":"AI-gile ni dosegljiv: poskusi znova pozneje.","interest.title":"AI-gile: sporoči mi, ko se odpre alfa","interest.description":"Pusti e-naslov in izvedel boš, ko se odpre zaprta alfa ali beta AI-gile.","interest.h1":"🔔 Sporoči mi, ko se odpre","interest.lede":"AI-gile je v zaprti pred-alfi. Pusti e-naslov in napisali ti bomo enkrat, ko bo zate prostor.","interest.email":"Tvoj e-naslov","interest.which":"Kateri preizkus?","interest.alpha":"Zaprta alfa: zgodnja, groba, veliko sprememb","interest.beta":"Beta: bolj stabilna, pozneje","interest.both":"Katera koli, kar pride prej","interest.submit":"Zapiši me na seznam","interest.thanks":"Hvala! Si na seznamu.","interest.kept":"Hranimo samo tvoj e-naslov in izbrani preizkus, le za ta seznam. Brez novic, brez sledilnikov.","licence.title":"AI-gile: poslovna licenca","licence.description":"Uporabljaš AI-gile v podjetju? Zaprosi za brezplačno poslovno licenco.","licence.h1":"📜 Poslovna licenca","licence.lede":"Uporabljaš AI-gile v službi? Povej nam, kdo si in kaj počneš. Če to prinaša kaj dobrega, je licenca brezplačna.","licence.company":"Podjetje","licence.website":"Spletna stran","licence.what":"Kaj počneš","licence.how":"Kako to pomaga svetu","licence.email":"E-naslov","licence.submit":"Zaprosi","licence.thanks":"Hvala! Odgovorili bomo po e-pošti.","status.title":"Stanje AI-gile","status.h1":"Stanje AI-gile","status.quiet":"Vse mirno","status.checking":"Preverjanje …","status.offline":"Storitev stanja trenutno ni dosegljiva (poskušam znova)","status.updated":"posodobljeno {ago}","status.justNow":"pravkar","status.min":"pred {n} min","status.hours":"pred {n} h","status.days":"pred {n} d","live.h2":"Oglejte si, kako nastaja, v živo","live.caption":"Vsaka kartica je skrita: vidite obliko dela, ne besed.","live.watching.one":"v živo: gleda {n}","live.watching.other":"v živo: gledata {n}","live.offline":"Tabla v živo si malo oddahne. Poglejte kmalu znova.","live.cols":"Backlog|Na vrsti|V teku|Ekipa preverja|Zate, v testiranje|Za ekipo|Končano","live.last.now":"Zadnja kartica premaknjena pravkar","live.last.min.one":"Zadnja kartica premaknjena pred {n} minuto","live.last.min.two":"Zadnja kartica premaknjena pred {n} minutama","live.last.min.few":"Zadnja kartica premaknjena pred {n} minutami","live.last.min.other":"Zadnja kartica premaknjena pred {n} minutami","live.last.hour.one":"Zadnja kartica premaknjena pred {n} uro","live.last.hour.two":"Zadnja kartica premaknjena pred {n} urama","live.last.hour.few":"Zadnja kartica premaknjena pred {n} urami","live.last.hour.other":"Zadnja kartica premaknjena pred {n} urami","live.last.day.one":"Zadnja kartica premaknjena pred {n} dnevom","live.last.day.two":"Zadnja kartica premaknjena pred {n} dnevoma","live.last.day.few":"Zadnja kartica premaknjena pred {n} dnevi","live.last.day.other":"Zadnja kartica premaknjena pred {n} dnevi"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Prepuščeno."]},{"n":2,"texts":["Robotski kanban.","Agenti, urejeni.","Ideje, zgrajene."]},{"n":3,"texts":["Kanban za robote.","Ideje postanejo funkcije.","Brezplačen kanban agentov."]},{"n":5,"texts":["Kanban tabla, ki jo vodijo agenti.","Ti pišeš kartice. Agenti gradijo.","Brezplačno, lokalno, preizkušeno, malce noro."]},{"n":8,"texts":["Brezplačna kanban tabla, kjer delajo AI agenti.","Napiši idejo. Agenti jo zgradijo. Ti jo sprejmeš.","Agilnost za enega človeka in veliko potrpežljivih robotov."]},{"n":13,"texts":["Kanban tabla na tvojem računalniku, kjer kartice prevzemajo AI agenti in delajo nanje.","Napiši idejo. Ekipa agentov jo zgradi. Testnik jo preveri. Ti rečeš da.","Brezplačno, brez računov in sledilnikov: tabla, nekaj robotov in ti kot šef."]},{"n":21,"texts":["AI-gile je kanban tabla za delo z AI agenti, ki programirajo. Oni prevzemajo kartice, ti jih preizkušaš in sprejemaš.","Vsak projekt dobi vodjo in ekipo AI agentov. Napiši komentar k poljubni kartici in ekipa se loti dela.","Brezplačna osebna tabla opravil, ki teče na tvojem računalniku. Delavci so roboti. Da reči pa lahko samo ti."]},{"n":34,"texts":["Ideje daš na tablo. Ekipa AI agentov jih spremeni v delujoče funkcije, jih preizkusi in ti jih vrne s koraki za preizkus. Nič ni opravljeno, dokler tega ne rečeš ti.","AI-gile je domača kanban tabla, ki jo je Rich zgradil z veliko pomočjo agentov, ki jih zdaj sama vodi. Je brezplačna, teče na tvojem računalniku in jo deli s prijatelji, ne prodaja.","Predstavljaj si navadno kanban tablo s stolpci od Backlog do Končano, le da kartice prevzemajo AI agenti. Poročajo o napredku, vprašajo, ko obtičijo, in vedno počakajo na tvoje soglasje."]},{"n":55,"texts":["AI-gile je kanban tabla, kjer ekipo sestavljajo AI agenti. Vsak projekt ima vodjo, ki načrtuje delo, in pomočnike, ki ga gradijo. Ko je funkcija pripravljena, jo AI testnik preizkusi in naredi posnetek zaslona, nato pristane na tvoji skupini. Sprejmi jo ali napiši komentar in jo predelajo.","Začelo se je kot način, da si en človek zapomni veliko AI programerskih sej hkrati, nato pa zraslo v pravo tablo. Teče na tvojem računalniku, ne potrebuje računa in nima sledilnikov. Za prijatelje in radovedneže je brezplačna. Je tudi nedokončana, zato računaj na robove in občasno presenečenje.","Tukaj je poštena različica. Ideje moraš še vedno imeti ti, rezultate moraš še vedno preveriti ti. AI-gile naredi vse vmes: drži kartice urejene, zbudi pravega agenta, ko napišeš komentar, natančno pokaže, kaj se je spremenilo, in vse zloži v eno kratko skupino zate, ki jo zmoreš pregledati ob jutranji kavi. Ostalo je še vedno tvoje."]},{"n":89,"texts":["AI-gile je brezplačna kanban tabla, ki jo poganjaš na svojem računalniku. Namesto ljudi ima vsak projekt ekipo AI agentov: vodjo, ki tvoje ideje spremeni v kartice in načrt, in pomočnike, ki kartice prevzemajo po prednosti. Ko je nekaj zgrajeno, AI testnik sledi korakom testa in ti pokaže, kaj je videl. Potem čaka v eni skupini z imenom Zate. Sprejmeš ali napišeš komentar in ekipa poskusi znova. Nič ne pride do Končano brez tebe.","Nekaj reči, ki jih morda ne pričakuješ. Nočna straža polni stolpec Na vrsti, medtem ko spiš, in izbira kartice, ki od tebe ne potrebujejo odgovora. Števec žetonov kaže, koliko so agenti porabili danes in ta teden, Način brez žetonov pa jim ukaže, naj nehajo trošiti. S prijatelji si lahko pišeš, zasebna sporočila pa so šifrirana od konca do konca. Tabla govori približno 120 jezikov, tudi nizozemščino, flamščino, piratščino in klingonščino. Nič od tega ne stane niti centa in nihče ti tega niti ne poskuša prodati.","AI-gile je majhen osebni projekt, ne podjetje. Rich je želel skrbeti za več AI programerskih projektov, ne da bi odpiral vsako aplikacijo, zato je skupaj z agenti zgradil tablo in z njo zgradil še preostanek sebe. Je v zaprti pred-alfi, kar pomeni, da deluje, večinoma, za peščico prijateljev. Nima cenika, glasila ali načrta rasti. Teče na tvojem računalniku, brez računov in brez sledilnikov. Če se ti zdi uporabno, lahko zaprosiš za preizkus, ko se malo bolj odpre."]},{"n":144,"texts":["AI-gile je kanban tabla za enega človeka in veliko AI agentov. Teče na tvojem računalniku in je povsem brezplačna. Dodaš projekte in vsak dobi vodjo in majhno ekipo. S vodjo klepetaš, nekako kot na Discordu, in opišeš idejo; vodja jo spremeni v kartice in načrt ter počaka, da pritisneš Daj. Ekipa kartice obdela po prednosti s preprostim ukaznim vmesnikom, narejenim za jezikovne modele. Preden se karkoli vrne k tebi, AI testnik v kopiji aplikacije sledi korakom in priloži posnetek zaslona. Končano delo pristane na tvoji skupini s spremenjenimi datotekami in razlikami. Sprejmeš ga ali pustiš komentar in ekipa se zbudi ter poskusi znova. Kartico v Končano lahko premakneš samo ti, nihče drug. Brez računov, brez sledilnikov, brez piškotkov, vse na tvojem računalniku.","Dan z AI-gile, približno. Zvečer pustiš nekaj komentarjev: ta gumb je na napačnem mestu, tisti seznam naj bo urejen, ali bi lahko imeli temni način. Greš spat. Agenti preberejo komentarje, naredijo spremembe, jih preizkusijo in ti jih vrnejo. Če stolpec Na vrsti usahne, ga nočna straža napolni iz zaloge s karticami, ki od tebe ne potrebujejo odgovora. Zjutraj je ena kratka skupina: nekaj vprašanj in nekaj reči za preizkus, vsaka s koraki, ki jih zmore tudi zaspan človek, in s posnetkom, da deluje. Preklikaš, sprejmeš dobre in preostale pošlješ nazaj. Števec žetonov pokaže, kaj je vse to porabilo, Način brez žetonov pa je tu za skromnejše tedne. Potem zajtrkuješ, pri čemer ti agenti zaenkrat še ne znajo pomagati.","Najprej to, kaj AI-gile ni. Ni startup, ni naprodaj in nihče ne zbira tvojih podatkov. Je brezplačna tabla, ki teče na tvojem računalniku, brez računov, brez sledilnikov in brez piškotkov. Kaj pa je: eno pregledno mesto, kjer vidiš vse AI programerske projekte hkrati, kjer ekipa agentov dela kartice, ti pa odločaš. Združuje sorodne kartice, popravlja zmedene naslove in pazi, da koda ostane vitka. Govori približno 120 jezikov, od nizozemščine in flamščine do piratščine in klingonščine. Prijatelji si lahko pišejo zasebno in šifrirano. Zgradil jo je Rich z množico potrpežljivih agentov, večinoma s pomočjo same sebe. Je v zaprti pred-alfi, zato je mestoma groba. Če se ti zdi zabavno, lepo vprašaj in morda prideš noter prej."]}],"quips":{"1":"Ena beseda. Drzno. Morda preveč.","3":"Tri besede. Že zdaj bolj poštene od večine strani s produkti.","8":"Osem besed. Še vedno krajše od stand-upa.","21":"Dolžine so mimogrede story pointi. Seveda so.","55":"Petinpetdeset besed. Medtem ko si bral, sta se končali dve kartici.","144":"To je dolga. 233 ne obstaja. Agenti so šli spat."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Čisto prvi pogovor, še preden je obstajala kakršna koli koda.","first-board.name":"Prva tabla","first-board.line":"Tabla, ki spremlja lastno gradnjo: kartice, stolpci, vleci in spusti, projekti.","team-roles.name":"Ekipa in vloge","team-roles.line":"Profili agentov, predloge ekip, prostori in kdo počne kaj.","install.name":"Namestitev in izdaje","install.line":"Zip, ki ga lahko namesti tudi prijatelj, samodejne posodobitve, kanali in vrnitev nazaj.","usage-saver.name":"Varčevanje s porabo","usage-saver.line":"Izmeri, koliko stanejo zagoni, drži kodo vitko, varuj svojo omejitev.","friends.name":"Prijatelji in deljenje","friends.line":"Zasebna sporočila, premešan relej, povabila, vloge in deljeni projekti.","languages.name":"Jeziki","languages.line":"Vsako besedilo zaslona v jezikovni datoteki, najprej nizozemščina in flamščina.","ai-tester.name":"AI testnik","ai-tester.line":"Testnik najprej preveri vsako predajo in pokaže, kaj je videl.","website.name":"Spletna stran","website.line":"aigile.lol, predstavitev in ta časovnica.","streaming.name":"Klepet in pretakanje","streaming.line":"Discord, Twitch, OBS, način pretakalca, GIF-i in emojiji.","no-ai.name":"Izdaja brez AI","no-ai.line":"Tabla za ljudi, ki programirajo brez AI, in javne table.","night-watch.name":"Nočna straža","night-watch.line":"Stražar in Scrum Master držita ekipe pri delu, medtem ko spiš.","p-more.name":"Vse ostalo","p-more.line":"Manjše ideje, ki še čakajo na vrsto.","p-android.name":"Telefon in Android","p-android.line":"Do table s telefona, nato domača aplikacija za Android.","p-release.name":"Alfa in naprej","p-release.line":"Zaprta alfa, živa stran, nato beta.","p-languages.name":"Več jezikov","p-languages.line":"Več kot sto jezikov in potopitveni način za učence.","p-engines.name":"Več AI motorjev","p-engines.line":"Izberi Claude, Codex ali Gemini za vsakega agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake tveganja, vrata združevanja, kartice incidentov in varovalke.","p-self.name":"Skrb zate","p-self.line":"Način utrujenosti, opomniki za skrb zase in 4:20.","p-servers.name":"Strežniki in rast","p-servers.line":"Globalne nastavitve strežnika, vloge in načrtovanje rasti.","p-livestream.name":"Dodatki za pretakanje","p-livestream.line":"Twitch klepet, emojiji po meri in javen živ pogled."},"words":{"button":"📖 Razvijalske besede","h":"📖 Razlaga razvijalskih besed","intro":"Besede, ki jih uporabljajo razvijalci (in AI ekipe), v preprostem jeziku.","search":"Poišči besedo …","none":"Nobena beseda se ne ujema.","close":"Zapri","list":[{"id":"backlog","word":"Backlog","text":"Ideje in delo, ki še nista načrtovana. Nič od tega se ne dela, dokler se ne premakne v stolpec Na vrsti."},{"id":"sprint","word":"Sprint","text":"Kratko obdobje dela (pogosto teden ali dva) z dogovorjenim naborom kartic, ki jih je treba dokončati.","also":["sprints","sprinti","sprint"]},{"id":"standup","word":"Stand-up","text":"Hiter pregled: kaj je kdo naredil, kaj dela naprej in kaj ga ovira.","also":["standup","stand-ups","stand-upi"]},{"id":"bug","word":"Bug","text":"Nekaj, kar ne deluje tako, kot bi moralo.","also":["bugs","bugi","napaka","napake"]},{"id":"test","word":"Test","text":"Preizkus dokončanega dela, da preveriš, ali dela, kar je bilo zahtevano, preden ga sprejmeš.","also":["tests","testi"],"noTip":1},{"id":"commit","word":"Commit","text":"Shranjen posnetek kode s kratkim zapiskom o spremembah. Na vsakega se lahko kadar koli vrneš.","also":["commits","commiti"]},{"id":"push","word":"Push","text":"Pošiljanje shranjenih posnetkov (commitov) iz tega računalnika na GitHub, da so na varnem in na voljo drugim."},{"id":"branch","word":"Branch","text":"Ločena veja dela v kodi, da je spremembe mogoče delati, ne da bi se dotaknili glavne različice.","also":["branches","veja","veje"]},{"id":"merge","word":"Merge","text":"Združitev sprememb veje nazaj v glavno različico."},{"id":"repo","word":"Repo","text":"Mapa projekta s kodo in celotno zgodovino commitov, običajno shranjena tudi na GitHubu.","also":["repository","repozitorij"]},{"id":"refactor","word":"Refactor","text":"Urejanje kode brez spremembe njenega delovanja: manjše datoteke, jasnejša imena, manj ponavljanja."},{"id":"deploy","word":"Deploy","text":"Objava nove različice v živo, na primer na strežnik, kjer jo ljudje uporabljajo."},{"id":"kanban","word":"Kanban","text":"Tabla s stolpci (Na vrsti, V teku, Končano), kjer se kartice med delom premikajo od leve proti desni."},{"id":"wip","word":"WIP limit","text":"Delo v teku: največ kartic, ki jih sme imeti stolpec, da ekipa stvari dokonča, preden začne nove.","also":["WIP","omejitev dela v teku"]},{"id":"pr","word":"Pull request","text":"Prošnja, da se spremembe veje preverijo in združijo v glavno različico.","also":["PR"]},{"id":"hook","word":"Hook","text":"Majhen ukaz, ki se sam zažene ob določenem trenutku, npr. ko se začne seja AI, da ekipa sliši tvoje komentarje.","also":["hooks","kljuka","kljuke"]},{"id":"token","word":"Token","text":"Enota, v kateri se šteje poraba AI: približno nekaj črk prebranega ali napisanega besedila. Manj žetonov pomeni, da ti ostane več paketa.","also":["tokens","žeton","žetoni"]},{"id":"agent","word":"Agent","text":"AI, ki samostojno dela na nalogi: bere kodo, spreminja, izvaja preverjanja in poroča.","also":["agents","agenti"]}]}};
